mapper.sql:
SELECT s.*
FROM proj_project_stage s
WHERE s.tenant_id = #{query.tenantId}
  AND s.project_id = #{query.projectId}
  AND s.deleted = b'0'
  AND (s.stage_code = #{query.currentStageCode}
    OR s.sort_order = (SELECT MIN(next_stage.sort_order)
                       FROM proj_project_stage next_stage
                       WHERE next_stage.tenant_id = #{query.tenantId}
                         AND next_stage.project_id = #{query.projectId}
                         AND next_stage.deleted = b'0'
                         AND next_stage.sort_order > (SELECT current_stage.sort_order
                                                        FROM proj_project_stage current_stage
                                                        WHERE current_stage.tenant_id = #{query.tenantId}
                                                          AND current_stage.project_id = #{query.projectId}
                                                          AND current_stage.stage_code = #{query.currentStageCode}
                                                          AND current_stage.deleted = b'0')))
ORDER BY s.sort_order, s.id

mapper.update:
UPDATE proj_project_stage
SET status = #{query.targetStatus},
    version = version + 1,
    updater = #{query.updater},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND id = #{query.stageId}
  AND version = #{query.expectedVersion}
   AND status = #{query.expectedStatus}
   AND deleted = b'0'
